\begin{tikzpicture}
\begin{axis}[
    width=\textwidth,
    height=0.76\textwidth,
    xmin=-1, xmax=1,
    ymin=-6, ymax=6,
    axis lines=middle,
    xlabel={\(x\)},
    ylabel={\(y\)},
    xtick={-1,0,1},
    ytick={-6,0,6},
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
    title={small window}
]
\addplot[thick, domain=-1:1, samples=100] {x^3-6*x};
\end{axis}
\end{tikzpicture}

\begin{tikzpicture}
\begin{axis}[
    width=\textwidth,
    height=0.76\textwidth,
    xmin=-3, xmax=3,
    ymin=-10, ymax=10,
    axis lines=middle,
    xlabel={\(x\)},
    ylabel={\(y\)},
    xtick={-3,-2,-1,0,1,2,3},
    ytick={-10,-5,0,5,10},
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
    title={wider window}
]
\addplot[thick, domain=-3:3, samples=160] {x^3-6*x};
\end{axis}
\end{tikzpicture}

\begin{tikzpicture}
\begin{axis}[
    width=\textwidth,
    height=0.74\textwidth,
    xmin=0, xmax=1,
    ymin=-1.2, ymax=1.2,
    axis lines=middle,
    xlabel={\(x\)},
    ylabel={\(y\)},
    xtick={0,0.5,1},
    ytick={-1,0,1},
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
    title={poor sampling}
]
\addplot[thick, domain=0:1, samples=101] {sin(deg(100*pi*x))};
\addplot[only marks, mark=*, mark size=0.45pt, domain=0:1, samples=101] {sin(deg(100*pi*x))};
\end{axis}
\end{tikzpicture}

\begin{tikzpicture}
\begin{axis}[
    width=\textwidth,
    height=0.74\textwidth,
    xmin=0, xmax=1,
    ymin=-1.2, ymax=1.2,
    axis lines=middle,
    xlabel={\(x\)},
    ylabel={\(y\)},
    xtick={0,0.5,1},
    ytick={-1,0,1},
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
    title={finer sampling}
]
\addplot[thick, domain=0:1, samples=1200] {sin(deg(100*pi*x))};
